mapper.select:
SELECT 
FROM tenant_quota_usage
WHERE tenant_id = #{tenantId}
  AND quota_key = #{quotaKey}
  AND period_key = #{periodKey}
  AND is_deleted = 0
LIMIT 1

mapper.insert:
INSERT INTO tenant_quota_usage(
    id, tenant_id, quota_key, used_value, limit_value, period_key,
    is_deleted, gmt_created, gmt_modified, gmt_deleted
) VALUES (
    #{id}, #{tenantId}, #{quotaKey}, #{usedValue}, #{limitValue}, #{periodKey},
    #{isDeleted}, #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)
ON DUPLICATE KEY UPDATE
    used_value = used_value + VALUES(used_value),
    gmt_modified = VALUES(gmt_modified)

mapper.update:
UPDATE tenant_quota_usage
SET used_value = GREATEST(used_value + #{delta}, 0),
    gmt_modified = #{gmtModified}
WHERE tenant_id = #{tenantId}
  AND quota_key = #{quotaKey}
  AND period_key = #{periodKey}
  AND is_deleted = 0

UPDATE tenant_quota_usage
SET used_value = #{usedValue},
    gmt_modified = #{gmtModified}
WHERE tenant_id = #{tenantId}
  AND quota_key = #{quotaKey}
  AND period_key = #{periodKey}
  AND is_deleted = 0

UPDATE tenant_quota_usage
SET limit_value = #{limitValue},
    gmt_modified = #{gmtModified}
WHERE tenant_id = #{tenantId}
  AND quota_key = #{quotaKey}
  AND period_key = #{periodKey}
  AND is_deleted = 0
